// Simple mock of Kraftly's API. Built for the demo -- NOT for production.
// Webbmakarna AB / M & J
const express = require("express");
// Konfiguration kommer från miljön. Lokalt läses .env (om den finns).
try {
  process.loadEnvFile();
} catch {
  // ingen .env – helt normalt i en container
}

// API_KEYS = flera klienter, en nyckel var: "volt:abc123,ampere:def456"
// API_KEY  = en enda nyckel (det räcker lokalt)
const keys = new Map(
  (
    process.env.API_KEYS ||
    (process.env.API_KEY ? `lokal:${process.env.API_KEY}` : "")
  )
    .split(",")
    .map((entry) => entry.trim())
    .map((entry) => [
      entry.slice(0, entry.indexOf(":")),
      entry.slice(entry.indexOf(":") + 1),
    ])
    .filter(([name, key]) => name && key)
    .map(([name, key]) => [key, name]),
);
if (keys.size === 0) {
  console.error(
    "API_KEY saknas. Lokalt: kopiera .env.example till .env. I molnet: sätt variabeln hos plattformen.",
  );
  process.exit(1);
}

const app = express();
app.use(express.json());

// CORS -- opens everything so it just works
// Varje anrop till /api måste ha en giltig nyckel
app.use("/api", (req, res, next) => {
  const auth = req.get("Authorization") || "";
  const token = auth.startsWith("Bearer ") ? auth.slice(7) : "";

  if (token !== "fake-token-123") {
    console.log(
      `401 ${req.method} ${req.originalUrl} – saknad eller ogiltig token`,
    );
    return res.status(401).json({ error: "Saknad eller ogiltig token" });
  }

  next();
});

app.use((req, res, next) => {
  res.header("Access-Control-Allow-Origin", "*");
  res.header("Access-Control-Allow-Headers", "*");
  res.header("Access-Control-Allow-Methods", "*");
  if (req.method === "OPTIONS") return res.sendStatus(200);
  next();
});

const user = {
  id: 1,
  name: "Anna Andersson",
  email: "anna.andersson@example.com",
  address: "Solvägen 12, 802 67 Gävle",
  contract: "Rörligt pris",
  customerNo: "K-104233",
};

const invoices = [
  {
    id: "F-2026-06",
    period: "Juni 2026",
    amount: 412,
    status: "Obetald",
    due: "2026-07-31",
  },
  {
    id: "F-2026-05",
    period: "Maj 2026",
    amount: 486,
    status: "Betald",
    due: "2026-06-30",
  },
  {
    id: "F-2026-04",
    period: "April 2026",
    amount: 655,
    status: "Betald",
    due: "2026-05-31",
  },
  {
    id: "F-2026-03",
    period: "Mars 2026",
    amount: 918,
    status: "Betald",
    due: "2026-04-30",
  },
  {
    id: "F-2026-02",
    period: "Februari 2026",
    amount: 1204,
    status: "Betald",
    due: "2026-03-31",
  },
  {
    id: "F-2026-01",
    period: "Januari 2026",
    amount: 1345,
    status: "Betald",
    due: "2026-02-28",
  },
];

const consumption = {
  unit: "kWh",
  months: [
    "Jul",
    "Aug",
    "Sep",
    "Okt",
    "Nov",
    "Dec",
    "Jan",
    "Feb",
    "Mar",
    "Apr",
    "Maj",
    "Jun",
  ],
  values: [210, 195, 260, 340, 520, 680, 730, 640, 470, 320, 240, 205],
  pricePerKwh: 1.42,
};

// anyone gets in, we'll add real auth later(TM)
app.post("/api/login", (req, res) => {
  res.json({ token: "fake-token-123", name: user.name });
});

app.get("/api/user", (req, res) => res.json(user));

app.get("/api/consumption", (req, res) => {
  // quick fix: dashboard felt too fast in the demo, added a delay so the spinner shows /J
  setTimeout(() => res.json(consumption), 600);
});

app.get("/api/invoices", (req, res) => res.json(invoices));

app.post("/api/move", (req, res) => {
  console.log("Move request:", req.body);
  res.json({
    ok: true,
    ref: "FLYTT-" + Math.floor(Math.random() * 90000 + 10000),
  });
});

app.put("/api/user", (req, res) => {
  Object.assign(user, req.body);
  res.json(user);
});

app.get("/healthz", (req, res) => {
  res.sendStatus(200);
});

const port = process.env.PORT || 4000;
app.listen(port, () =>
  console.log(`Mock API on port ${port} – ${keys.size} nyckel/nycklar laddade`),
);

import { readdir, readFile } from "node:fs/promises";
import { gzipSync } from "node:zlib";
import path from "node:path";

const assetsDir = "dist/assets";
const budgetKB = 55;

const files = await readdir(assetsDir);

const dashboardFile = files.find((file) => file.startsWith("DashboardView-"));

if (!dashboardFile) {
  console.error("Dashboardens JavaScript-fil hittades inte.");
  process.exit(1);
}

const filePath = path.join(assetsDir, dashboardFile);
const content = await readFile(filePath);
const sizeKB = gzipSync(content).length / 1024;

console.log(`Dashboard JS: ${sizeKB.toFixed(2)} KB gzip`);
console.log(`Budget: ${budgetKB} KB gzip`);

if (sizeKB > budgetKB) {
  console.error("JavaScript-budgeten överskrids!");
  process.exit(1);
}

console.log("JavaScript-budgeten klaras.");

// API client for Kraftly "Mina sidor"
//
// Ingen nyckel här. Allt i frontendkoden hamnar i JavaScript-filen som browsern laddar
// ner – en nyckel här är publik för alla som trycker F12. Appen anropar /api relativt.
// Servern framför appen (Vite lokalt, nginx i containern) lägger på nyckeln.
import { getAccessToken, setAccessToken } from "./token";

const BASE_URL = "";
const API_BASE = "/api/v2";

const request = async (path, options = {}) => {
  const token = getAccessToken();

  const res = await fetch(BASE_URL + path, {
    ...options,
    headers: {
      "Content-Type": "application/json",
      ...(token ? { Authorization: `Bearer ${token}` } : {}),
      ...options.headers,
    },
  });
  if (!res.ok) {
    console.log("API error", res.status);
    throw new Error("API error " + res.status);
  }
  return res.json();
};

export const login = (email, password) =>
  request(API_BASE + "/auth/login", {
    method: "POST",
    body: JSON.stringify({ email, password }),
  });

export const fetchUser = () => request(API_BASE + "/user");
export const fetchConsumption = () => request(API_BASE + "/consumption");
export const fetchInvoices = () => request(API_BASE + "/invoices");
export const submitMove = (data) =>
  request(API_BASE + "/move", { method: "POST", body: JSON.stringify(data) });
export const saveUser = (data) =>
  request(API_BASE + "/user", { method: "PUT", body: JSON.stringify(data) });

// Called once when the app starts, so a page reload doesn't log the user out.
// The refresh cookie (set by the server at login) is sent automatically.
export const initAuth = async () => {
  try {
    const res = await fetch(BASE_URL + API_BASE + "/auth/refresh", {
      method: "POST",
      credentials: "include",
    });
    if (!res.ok) {
      setAccessToken(null);
      return false;
    }
    const data = await res.json();
    setAccessToken(data.accessToken);
    return true;
  } catch {
    setAccessToken(null);
    return false;
  }
};

import { ref } from "vue";
import { defineStore } from "pinia";
import { fetchUser, saveUser } from "../services/api";

export const useUserStore = defineStore("user", () => {
  const user = ref(null);
  const loading = ref(false);

  const load = async () => {
    loading.value = true;
    try {
      user.value = await fetchUser();
    } catch (e) {
      console.log(e);
    }
    loading.value = false;
  };

  const save = async (data) => {
    user.value = await saveUser(data);
    alert("Sparat!");
  };

  return { user, loading, load, save };
});

